"""Verify the signed passive IDS, fresh public rules, real loopback events and cold recovery."""
from pathlib import Path
import contextlib
import ftplib
import io
import socket
import ssl
import hashlib
import http.cookiejar
import json
import os
import platform
import re
import secrets
import sqlite3
import stat
import subprocess
import sys
import time
import traceback
from urllib.parse import urlencode
import urllib.error
import urllib.request

os.umask(0o077)
architecture={'x86_64':'amd64','aarch64':'arm64'}[platform.machine()]
assert os.geteuid()==0 and len(sys.argv) in (2,3)
inputs=Path(sys.argv[1]).resolve(strict=True)
pins=json.loads((inputs/'assets.json').read_text())
os_identity=dict(line.split('=',1) for line in Path('/etc/os-release').read_text().splitlines() if '=' in line and not line.startswith('#'))
case=pins['OS_case']
actual_platform=os_identity['ID']+'-'+os_identity['VERSION_ID'].strip('"')
assert actual_platform=='ubuntu-24.04'
assert case['platform']==actual_platform and case['architecture']==pins['architecture']==architecture
assert Path('/etc/hostname').read_text().strip()==pins['OS_case']['hostname']
recovering=len(sys.argv)==3
base=Path(sys.argv[2]).resolve(strict=True) if recovering else Path('/opt/panel-ids-c202-qa-'+secrets.token_hex(16))
assert base.parent==Path('/opt') and re.fullmatch(r'panel-ids-c202-qa-[a-f0-9]{32}',base.name)
out=base/'evidence'
if not recovering:out.mkdir(mode=0o700,parents=True)
assert base.stat().st_uid==out.stat().st_uid==0 and stat.S_IMODE(out.stat().st_mode)==0o700
boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip()
proof={'ok':False,'base':str(base),'boot':boot,'platform':actual_platform,'architecture':architecture,
       'source_inputs_sha256':pins['source_inputs_sha256'],'Main_changed':False,'all50_commercial':False}
client=urllib.request.build_opener(urllib.request.ProxyHandler({}),urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
local=urllib.request.build_opener(urllib.request.ProxyHandler({}))
origin='http://127.0.0.1:19100'
csrf=''
def sha(x):return hashlib.sha256(x).hexdigest()
def save(path,v):
    with path.open('x') as f:json.dump(v,f,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
def api(path,body=None,status=200,key=None):
    headers={'Origin':origin,'Content-Type':'application/json','X-CSRF-Token':csrf}
    if key:headers['Idempotency-Key']=key
    req=urllib.request.Request(origin+'/api'+path,None if body is None else json.dumps(body).encode(),headers)
    try:
        with client.open(req,timeout=90) as res:
            assert res.status==status and res.url==req.full_url
            return json.load(res)
    except urllib.error.HTTPError as error:
        if error.code==status:
            return json.loads(error.read(8192))
        raise

def wait_job(table,job,seconds):
    assert table in ('jobs','runtime_jobs') and re.fullmatch('[a-f0-9]{32}',job)
    end=time.monotonic()+seconds
    while time.monotonic()<end:
        with contextlib.closing(sqlite3.connect('file:/var/lib/panel/panel.db?mode=ro',uri=True)) as db:
            db.row_factory=sqlite3.Row;db.execute('PRAGMA query_only=ON')
            row=db.execute('SELECT * FROM '+table+' WHERE id=?',(job,)).fetchone()
        if row is not None and row['state'] not in ('queued','running'):
            assert row['state']=='succeeded' and not row['error'],row['error']
            return dict(row)
        time.sleep(1)
    raise TimeoutError(table)
def command(label,args,timeout=120):
    with(out/(label+'.stdout')).open('xb') as stdout,(out/(label+'.stderr')).open('xb') as stderr:
        result=subprocess.run(args,stdin=subprocess.DEVNULL,stdout=stdout,stderr=stderr,timeout=timeout)
    assert result.returncode==0,label
def sign_input_copy():
    dest=base/'verified-input';dest.mkdir(mode=0o700)
    for name,digest in pins['files'].items():
        assert re.fullmatch(r'[A-Za-z0-9._-]+',name) and re.fullmatch('[a-f0-9]{64}',digest)
        with os.fdopen(os.open(inputs/name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC),'rb') as f:
            st=os.fstat(f.fileno())
            assert stat.S_ISREG(st.st_mode) and st.st_nlink==1 and 0<st.st_size<=64<<20
            raw=f.read((64<<20)+1)
        assert len(raw)==st.st_size and sha(raw)==digest
        with(dest/name).open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    assert sha((dest/'release-signing-dev.pub').read_bytes())=='4ccfcc861d56a41e3ba7f7ace7e2432c815f366c58448d783df92c6632f01339'
    return dest

RULES={'LICENSE': '', 'classification.config': '', 'reference.config': '', 'manifest.json': '', 'BSD-License.txt': '', 'et-open.rules': ''}
EXPECTED_RULE_MANIFEST='62334f9a20317654453a5cadbfd4989b31ccbc70f9caba64da100d301f0d0a7a'

import base64,shutil,http.server,http.client,threading
module='/app-modules/network-threat-detection'
configuration=Path('/etc/panel/network-ids/suricata.yaml')
event_log=Path('/var/lib/panel-network-ids/logs/eve.json')
private=Path('/etc/panel/security-apps/modules/network-threat-detection')
def wait(read,ready,seconds):
    deadline=time.monotonic()+seconds
    while time.monotonic()<deadline:
        result=read()
        if ready(result):return result
        time.sleep(1)
    raise TimeoutError('Native IDS operation did not settle')
def report():return api(module+'/ids-report',{})
def operation(action,body):
    result=api(module+'/'+action,body,202,secrets.token_hex(16))
    row=wait(lambda:api(module+'/operations/'+result['id']),lambda v:v['state'] not in ('queued','running'),650)
    assert row['state']=='succeeded',row.get('error')
    return row
def revision():return (report().get('configuration') or {}).get('revision',0)
class Marker(http.server.BaseHTTPRequestHandler):
    def log_message(self,*args):pass
    def do_TRACE(self):
        self.send_response(200);self.send_header('Content-Length','2');self.end_headers();self.wfile.write(b'OK')
def trace_alert():
    server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Marker)
    thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
    try:
        for _ in range(3):
            conn=http.client.HTTPConnection('127.0.0.1',server.server_port,timeout=5)
            conn.request('TRACE','/owned-ids-fixture');response=conn.getresponse()
            assert response.status==200 and response.read()==b'OK'
            conn.close()
        result=wait(report,lambda r:any(e['signature_id']==9000004 and e['destination_port']==server.server_port for e in r['events']['alerts']),90)
        assert result['passive_only'] and result['process_verified']
        return [e for e in result['events']['alerts'] if e['signature_id']==9000004 and e['destination_port']==server.server_port]
    finally:
        server.shutdown();server.server_close();thread.join(timeout=3)
def native_syntax(native):
    import tempfile
    rules=Path(tempfile.mkdtemp(prefix='panel-public-ids-rules-',dir='/run'))
    rules.chmod(0o755)
    # Only the public upstream rule and licence files enter this traversable folder.
    # The root-owned private evidence and signed-input parent retains mode 0700.
    for name,value in RULES.items():
        (rules/name).write_bytes(base64.b64decode(value));(rules/name).chmod(0o644)
    manifest=json.loads((rules/'manifest.json').read_bytes())
    assert sha((rules/'manifest.json').read_bytes())==EXPECTED_RULE_MANIFEST
    for name,digest in manifest['files_sha256'].items():assert sha((rules/name).read_bytes())==digest
    root=Path('/opt/panel/app-modules/network-threat-detection')/native['prefix']
    assert re.fullmatch('apt-[a-f0-9]{16}',native['prefix'])
    command('fresh-rules-native-syntax',['runuser','-u','panel-network-ids','--','env','-i','PATH=/usr/sbin:/usr/bin:/sbin:/bin','LANG=C','LD_LIBRARY_PATH='+str(root/'libraries'),str(root/'bin/suricata'),'-T','--init-errors-fatal','--strict-rule-keywords','--set','outputs.0.eve-log.enabled=no','--set','classification-file='+str(rules/'classification.config'),'--set','reference-config-file='+str(rules/'reference.config'),'-l','/tmp','-c',str(configuration),'-S',str(rules/'et-open.rules')],180)
    assert manifest['enabled_rule_count']==1518 and manifest['dependency_rule_count']==2
    return manifest
try:
    if not recovering:
        assert not any(os.path.lexists(p) for p in ('/opt/panel','/etc/panel','/var/lib/panel'))
        staged=sign_input_copy();archive=staged/('panel-'+pins['version']+'-linux-'+architecture+'.tar.gz')
        signer=['python3','-I','-B',str(staged/'signed-release.py')]
        trust=['--public-key',str(staged/'release-signing-dev.pub')]
        command('signed-verify',signer+['verify',str(archive)]+trust)
        command('signed-install',signer+['install',str(archive)]+trust,1800)
    creds=json.loads(Path('/etc/panel/first-login.json').read_bytes())
    csrf=api('/login',{key:creds[key] for key in ('username','password')})['csrf'];creds.clear()
    if not recovering:
        page=api('/app-registry?refresh=1')
        assert not page['source']['stale'] and page['source']['resolved_commit']==pins['served_head']
        item,=[v for v in page['catalog']['apps'] if v['id']=='network-threat-detection']
        assert item==pins['ids'] and item['version']=='1.3.2'
        job=api('/app-registry/network-threat-detection/install',{'expected_version':item['version'],'expected_sha256':item['sha256']},202,secrets.token_hex(16))['job_id']
        wait_job('runtime_jobs',job,650)
        prep=api(module+'/ids-prepare',{'prepare_ids':True})
        assert prep['capture_started'] is False
        ready=wait(report,lambda v:v['runtime_ready'],1250)
        assert ready['engine_support']['supported'] and not ready['process_verified']
        native=json.loads((private/'native-runtime.json').read_bytes())
        operation('ids-config',{'expected_revision':revision(),'network_interface':'lo','home_networks':['127.0.0.1/32','::1/128']})
        manifest=native_syntax(native)
        operation('ids-start',{'expected_revision':revision()})
        alerts=trace_alert()
        operation('ids-stop',{'expected_revision':revision()})
        stopped=report()
        assert not stopped['process_verified'] and not stopped['boot_enabled']
        assert any(e['signature_id']==9000004 for e in stopped['events']['alerts'])
        raw=event_log.read_bytes()
        assert raw and len(raw)<=8<<20
        original_alerts=stopped['events']['alerts']
        assert all(a in original_alerts for a in alerts)
        state={'boot':boot,'config_sha':sha(configuration.read_bytes()),'runtime_sha':sha((private/'native-runtime.json').read_bytes()),
            'alerts':original_alerts,'rule_manifest_sha256':EXPECTED_RULE_MANIFEST,'log_sha':sha(raw),'log_bytes':len(raw)}
        save(base/'state.json',state);save(out/'preboot-native-rules.json',{'manifest':manifest,'engine':ready['engine_support'],'alerts':alerts})
        proof.update(ok=True,powerloss_ready=True,phase='before-reboot',signed_ids_version='1.3.2',
            native_rule_syntax_verified=True,rules=1518,rule_manifest_sha256=EXPECTED_RULE_MANIFEST,real_loopback_alerts=True,stop_preserved_alerts=True)
    else:
        state=json.loads((base/'state.json').read_bytes());assert state['boot']!=boot
        assert sha(configuration.read_bytes())==state['config_sha']
        assert sha((private/'native-runtime.json').read_bytes())==state['runtime_sha']
        before=report()
        save(out/'postboot-original-ids-report.json',before)
        assert not before['process_verified'] and not before['boot_enabled']
        assert all(a in before['events']['alerts'] for a in state['alerts'])
        raw=event_log.read_bytes()
        assert len(raw)==state['log_bytes'] and sha(raw)==state['log_sha']
        save(out/'postboot-original-log-identity.json',{'bytes':len(raw),'sha256':sha(raw),'original_alerts':state['alerts']})
        operation('ids-start',{'expected_revision':revision()})
        alerts=trace_alert()
        operation('ids-stop',{'expected_revision':revision()})
        final=report()
        assert all(a in final['events']['alerts'] for a in state['alerts'])
        appended=event_log.read_bytes()
        assert len(appended)>state['log_bytes'] and sha(appended[:state['log_bytes']])==state['log_sha']
        save(out/'postboot-real-alerts.json',alerts)
        save(out/'postboot-original-and-new-ids-report.json',final)
        proof.update(ok=True,phase='after-reboot',prior_boot=state['boot'],signed_ids_version='1.3.2',
            actual_capture_recovered=True,original_config_and_runtime_preserved=True,retained_alerts=True,
            original_log_bytes_preserved=True,original_alert_identities_preserved=True,new_alert_appended=True)
except BaseException:
    proof['failure']=traceback.format_exc()
finally:
    if csrf:
        try:api('/logout',{})
        except Exception:proof['ok']=False
    save(out/('phase2.json' if recovering else 'phase1.json'),proof)
    print(json.dumps(proof),flush=True)
sys.exit(0 if proof['ok'] else 1)
